// ASCII portrait engine, adapted from ascii-face-avatar.html so it draws into a canvas on the page itself
// (no iframe, so the page also works when opened straight from disk). Generated by build_engine.py; the
// effects, depth model and camera tracking are unchanged from the original.
window.createAsciiPortrait = function (canvas, preview, opts = {}) {
const PORTRAITS = window.PORTRAITS;
const EMBED = true;
const RAINBOW_ROWS = 14;
let rainbow = false;
let still = false, now = 0, t = 0, px = -1e4, py = -1e4, power = 0, visible = true;
function report() { opts.onChange?.({ effect: current, photo: currentPhoto, camera: !!cameraStream, starting, hint: hint.textContent }); }
function setLook({ ground, ink, pushed, colorful }) {
  rainbow = !!colorful;
  canvas.style.setProperty("--ground", ground);
  canvas.style.setProperty("--ink", ink);
  canvas.style.setProperty("--pushed", pushed);
  if (P) layout();
}

// Head turn depth: a rounded surface, with how fast it curves away, as fractions of the portrait.
const dome = (u, v, c, peak = 1) => {
  const nx = (u - c.x) / c.rx, ny = (v - c.y) / c.ry, s = Math.sqrt(Math.max(0, 1 - nx * nx - ny * ny));
  return { z: peak * s, sx: -peak * nx / Math.max(.2, s) / c.rx, sy: -peak * ny / Math.max(.2, s) / c.ry };
};
// Straight-line interpolation through [u, v] points, for the curved edges of the cap brim.
const along = (points, u) => {
  for (let i = 1; i < points.length; i++) {
    if (u <= points[i][0]) {
      const [u0, v0] = points[i - 1], [u1, v1] = points[i];
      return v0 + (v1 - v0) * Math.max(0, (u - u0) / (u1 - u0));
    }
  }
  return points[points.length - 1][1];
};
const CAP_BRIM_TOP = [[0, .27], [.18, .21], [.43, .198], [.69, .22], [.95, .27], [1, .29]];
const CAP_BRIM_LIP = [[0, .345], [.18, .29], [.43, .276], [.69, .33], [.82, .405], [1, .33]];
const ramp = (from, to, x) => {
  const t = Math.max(0, Math.min(1, (x - from) / (to - from)));
  return t * t * (3 - 2 * t);
};
// The forms of a face around its landmarks: nose, brow, eye sockets, cheekbones, lips and chin.
function facialRelief(p, u, v) {
  const [l, r] = p.eyes, n = p.nose, m = p.mouth, eyeY = (l.y + r.y) / 2;
  return .22 * gauss(u, n.x, .035) * gauss(v, (eyeY + n.y) / 2, .07)
    + .3 * gauss(u, n.x, .055) * gauss(v, n.y, .045)
    + .12 * gauss(v, p.brow + .015, .02) * (gauss(u, l.x, .09) + gauss(u, r.x, .09))
    - .14 * gauss(v, eyeY, .03) * (gauss(u, l.x, .05) + gauss(u, r.x, .05))
    + .12 * gauss(v, n.y + .02, .06) * (gauss(u, l.x - .02, .08) + gauss(u, r.x + .02, .08))
    + .08 * gauss(u, m.x, .09) * gauss(v, m.y, .025)
    + .12 * gauss(u, m.x, .1) * gauss(v, m.y + .14, .05);
}

// Landmarks, as fractions of each portrait, for the blink, Gaze and Head turn.
Object.assign(PORTRAITS.flannel, {
  label: "Flannel",
  eyes: [{ x: .262, y: .420, rx: .066, ry: .027 }, { x: .590, y: .412, rx: .066, ry: .027 }],
  mouth: { x: .425, y: .66 }, nose: { x: .40, y: .52 }, head: { x: .44, y: .46, rx: .52, ry: .56 },
  mouthW: .128, mouthFill: [.19, .075],
  lid: [.075, .05], brow: .345, rootedFrom: .76, lightTone: 1,
  depth(u, v) {
    const d = dome(u, v, this.head), relief = facialRelief(this, u, v);
    d.z += relief * .9;
    return d;
  },
  // The photo already faces slightly left, so right has less room to turn.
  turn: { left: .85, right: .66, up: .45, down: .26 },
});
Object.assign(PORTRAITS.cap, {
  label: "Cap",
  eyes: [{ x: .299, y: .443, rx: .06, ry: .024 }, { x: .601, y: .452, rx: .06, ry: .024 }],
  mouth: { x: .447, y: .721 }, nose: { x: .46, y: .59 }, head: { x: .41, y: .51, rx: .5, ry: .54 },
  mouthW: .122, mouthFill: [.175, .062],
  lid: [.042, .026], brow: .369, rootedFrom: 2,
  // This photo's midtones are lifted to read on a dark ground; a light ground wants them back down.
  lightTone: 1.9,
  // One continuous surface, so the cap can never come away from the head: the crown eases back and the brim eases forward.
  depth(u, v) {
    const top = along(CAP_BRIM_TOP, u), lip = along(CAP_BRIM_LIP, u), across = (u - .45) / .6;
    const brim = ramp(top - .04, top + .02, v) * (1 - ramp(lip - .01, lip + .05, v));
    const crown = 1 - ramp(top - .06, top + .02, v);
    const face = ramp(lip, lip + .06, v);
    const d = dome(u, v, this.head), relief = facialRelief(this, u, v) * face;
    // The brim holds a steady depth out to its tip, so the tip travels with the head instead of being left behind.
    const held = d.z + (.62 * (1 - .22 * across * across) - d.z) * brim;
    d.z = held - .14 * crown + relief * .7;
    d.sx *= 1 - brim;
    d.sy *= 1 - brim;
    return d;
  },
  turn: { left: .55, right: .55, up: .34, down: .22 },
});

let P, SRC_W, SRC_H, SOURCE, EYES, MOUTH, NOSE, HEAD, PORTRAIT_ASPECT;
const ROBOT_DEPTH = .62;          // how far forward the robot sits, compared with the face in front of it
const TURN_DEPTH = .42;           // how far the face stands forward of the pivot, as a fraction of its width

const RAMP = " .`:-~=+*xoaXOZ#%8&@";
const TONES = 40, MIXES = 5;      // sprite sheet: TONES across, MIXES (ink to pushed colour) down
const CHAR_ASPECT = 0.6;          // monospaced advance / line height

const ctx = canvas.getContext("2d");
const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)");

let cells = [], sheet, bigSheet, dpr = 1, W = 0, H = 0, isDark = false, pushedColor = "#000";
let faceRows = 1, cx = 0, cy = 0, radius = 100, faceL = 0, faceT = 0, faceW = 0, faceH = 0, cellW = 1, cellH = 1;

for (const p of Object.values(PORTRAITS)) {
  p.source = Float32Array.from(p.data, ch => ch === " " ? -1 : (ch.charCodeAt(0) - 48) / 63);
  p.image = new Image();
  p.image.src = p.photo;
}

function usePortrait(id) {
  P = PORTRAITS[id];
  SRC_W = P.w; SRC_H = P.h; SOURCE = P.source;
  EYES = P.eyes; MOUTH = P.mouth; NOSE = P.nose; HEAD = P.head;
  PORTRAIT_ASPECT = P.w / P.h;
}

function averageTone(u0, v0, u1, v1) {
  const x0 = Math.floor(u0 * SRC_W), x1 = Math.max(x0 + 1, Math.ceil(u1 * SRC_W));
  const y0 = Math.floor(v0 * SRC_H), y1 = Math.max(y0 + 1, Math.ceil(v1 * SRC_H));
  let sum = 0, inside = 0, total = 0;
  for (let y = y0; y < y1 && y < SRC_H; y++) for (let x = x0; x < x1 && x < SRC_W; x++) {
    total++;
    const t = SOURCE[y * SRC_W + x];
    if (t >= 0) { sum += t; inside++; }
  }
  return inside / total < .5 ? -1 : sum / inside;
}

function hueColor(position) {
  const channel = n => {
    const k = (n + position * 12) % 12;
    // Light grounds get deeper, more saturated hues so the colors still read on cream.
    return Math.round(255 * ((isDark ? .74 : .5) - (isDark ? .24 : .4) * Math.max(-1, Math.min(k - 3, 9 - k, 1))));
  };
  return [channel(0), channel(8), channel(4)];
}

function makeSheet(scale, ink, pushed) {
  const w = Math.ceil(cellW * dpr * scale) + 2, h = Math.ceil(cellH * dpr * scale) + 2;
  const canvas = document.createElement("canvas");
  canvas.width = w * TONES;
  canvas.height = h * (MIXES + RAINBOW_ROWS);
  const s = canvas.getContext("2d");
  const style = getComputedStyle(canvas);
  // On a light ground the glyphs are drawn a little smaller and thinner, so the face reads as fine line work rather than a heavy block.
  const size = cellH * dpr * scale * (isDark ? 1 : .92);
  s.font = `${size}px ${style.getPropertyValue("--mono")}`;
  s.textAlign = "center";
  s.textBaseline = "middle";
  for (let m = 0; m < MIXES + RAINBOW_ROWS; m++) {
    const f = m / (MIXES - 1);
    const c = m < MIXES ? ink.map((v, i) => Math.round(v + (pushed[i] - v) * f)) : hueColor((m - MIXES) / RAINBOW_ROWS);
    for (let t = 0; t < TONES; t++) {
      const density = t / (TONES - 1);
      const glyph = RAMP[Math.min(RAMP.length - 1, Math.floor(density * RAMP.length))];
      const color = `rgba(${c[0]},${c[1]},${c[2]},${isDark ? .3 + .7 * density : .28 + .52 * density})`;
      s.fillStyle = color;
      s.fillText(glyph, (t + .5) * w, (m + .5) * h);
      // The font alone tops out at about a third coverage; thicken the densest glyphs to reach deeper tones.
      if (isDark && density > .55) {
        s.strokeStyle = color;
        s.lineWidth = (density - .55) * size * .16;
        s.strokeText(glyph, (t + .5) * w, (m + .5) * h);
      }
    }
  }
  return { canvas, w, h, scale };
}

function buildSheets() {
  const style = getComputedStyle(canvas);
  const rgb = name => {
    const hex = style.getPropertyValue(name).trim().slice(1);
    return [0, 2, 4].map(i => parseInt(hex.slice(i, i + 2), 16));
  };
  const ink = rgb("--ink"), pushed = rgb("--pushed");
  pushedColor = `rgb(${pushed.join(",")})`;
  // Bright pixels are dense on a dark ground and sparse on a light one, so the face stays a positive either way.
  isDark = parseInt(style.getPropertyValue("--ground").trim().slice(1, 3), 16) < 128;
  sheet = makeSheet(1, ink, pushed);
  bigSheet = makeSheet(2.4, ink, pushed);   // keeps Magnify sharp
}

const gauss = (v, mid, sd) => Math.exp(-((v - mid) ** 2) / (2 * sd * sd));

// The robot behind Scatter 2 is you in metal: your photo's light and dark set its plates, your hair and beard
// become wire mesh, and it wears your glasses and your smile.
function robotTone(u, v, tone) {
  const [l, r] = EYES, gap = r.x - l.x, mid = (l.x + r.x) / 2, eyeY = (l.y + r.y) / 2;
  const tall = w => w * PORTRAIT_ASPECT;    // a width in portrait height units, so shapes stay in proportion
  const lensW = gap * .4, lensH = tall(gap * .27), rimW = gap * .055, rimH = tall(gap * .075);

  for (const e of EYES) {
    const d = Math.hypot(u - e.x, (v - e.y) / PORTRAIT_ASPECT), R = gap * .15;
    if (d < R * .36) return 1;              // lit pupil
    if (d < R * .74) return .16;            // lens
    if (d < R) return .95;                  // bright ring
    const dx = Math.abs(u - e.x), dy = Math.abs(v - e.y);
    if (dx < lensW && dy < lensH) return .3;                     // glass
    if (dx < lensW + rimW && dy < lensH + rimH) return .03;      // frame
  }
  // Bridge and temple arms of the glasses.
  if (Math.abs(v - eyeY) < rimH * .8) {
    if (u > l.x + lensW && u < r.x - lensW) return .03;
    if (u < l.x - lensW || u > r.x + lensW) return .03;
  }

  // Speaker grille that follows the curve of a smile.
  const mw = gap * .6, side = (u - MOUTH.x) / mw;
  if (Math.abs(side) < 1) {
    const middle = MOUTH.y - side * side * tall(gap * .1), reach = Math.abs(v - middle), height = tall(gap * .085);
    if (reach < height) {
      const bars = (u - MOUTH.x + mw) / (gap * .11);
      return bars - Math.floor(bars) < .55 ? .94 : .06;
    }
    if (reach < height * 1.45) return .03;
  }

  // Hair, beard and brows are wire mesh.
  if (tone < .34) {
    const weave = (u + v / PORTRAIT_ASPECT) / (gap * .05);
    return weave - Math.floor(weave) < .5 ? .58 : .1;
  }

  // Everything else is plating, with seams and a rivet where they cross.
  const seamX = (u - mid) / (gap * .62) + .5, seamY = (v - eyeY) / tall(gap * .62) + .5;
  const offX = Math.abs(seamX - Math.round(seamX)), offY = Math.abs(seamY - Math.round(seamY));
  if (Math.hypot(offX, offY) * gap * .62 < gap * .04) return 1;
  if (offX < .02 || offY < .02) return .2;
  return .4 + .36 * Math.round(tone * 4) / 4;
}

function layout() {
  dpr = Math.min(window.devicePixelRatio || 1, 2);
  const box = canvas.getBoundingClientRect();
  W = box.width; H = box.height;
  // A hidden frame can report no size yet; the resize listener lays out again once it has one.
  if (W < 40 || H < 90) { cells = []; return; }
  canvas.width = Math.round(W * dpr);
  canvas.height = Math.round(H * dpr);

  const panelH = 0;
  panelTop = H - panelH;
  // An embedded avatar keeps a margin inside its frame, so scattered characters have somewhere to go.
  const room = EMBED ? H * .82 : Math.max(120, H - panelH - 20);
  faceH = Math.min(room, (EMBED ? W * .82 : W - 32) / PORTRAIT_ASPECT);
  faceW = faceH * PORTRAIT_ASPECT;
  isDark = parseInt(getComputedStyle(canvas).getPropertyValue("--ground").trim().slice(1, 3), 16) < 128;   // needed before the grid size
  // Finer grid than the original so eyes and glasses resolve; lighter while the camera runs.
  // Below about 3.2px per character drawing cost jumps sharply (over 3x in testing), so the light ground stops there.
  const cols = Math.max(48, Math.min(lite ? 110 : 175, Math.round(faceW / (lite ? 4.6 : (isDark ? 3.4 : 3.2)))));
  cellW = faceW / cols; cellH = cellW / CHAR_ASPECT;
  const rows = Math.round(faceH / cellH);
  faceRows = rows;
  faceL = (W - faceW) / 2; faceT = EMBED ? (H - faceH) / 2 : Math.max(8, (room - faceH) / 2 + 4);
  cx = W / 2; cy = faceT + faceH * .45;
  radius = EMBED ? faceW * .26 : Math.max(120, faceW * .36);   // a small avatar needs a proportionally small hole

  buildSheets();

  cells = [];
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const u = c / cols, v = r / rows;
    let tone = averageTone(u, v, u + 1 / cols, v + 1 / rows);
    if (tone < 0) continue;
    // Local contrast: push each character away from its neighbourhood, so small features (eyes, glasses, brows) stand out.
    const around = averageTone(u - 2 / cols, v - 2 / rows, u + 3 / cols, v + 3 / rows);
    if (around >= 0) tone = Math.max(0, Math.min(1, tone + (tone - around) * (isDark ? .3 : .9)));
    const u2 = u + .5 / cols, v2 = v + .5 / rows;

    let eye = 0, lash = 0, edx = 0, edy = 0, eyeSide = 0;
    for (const e of EYES) {
      const dx = (u2 - e.x) / e.rx, dy = (v2 - e.y) / e.ry, d = dx * dx + dy * dy;
      if (d < 1) {
        eye = 1 - d * d; edx = dx; edy = dy; eyeSide = e === EYES[1] ? 1 : 0;
        lash = Math.max(0, 1 - Math.abs(v2 - e.y - e.ry * .3) * rows * .9) * (1 - dx * dx);
      }
    }

    const shape = P.depth(u2, v2);
    const rooted = Math.min(1, Math.max(0, (v2 - P.rootedFrom) / .14));

    const mouthBox = Math.abs(u2 - MOUTH.x) < .24 && Math.abs(v2 - MOUTH.y) < .14;
    let fill = tone, mouthFade = 0;
    if (mouthBox) {
      const [fillX, fillY] = P.mouthFill;
      const n = Math.hypot((u2 - MOUTH.x) / fillX, (v2 - MOUTH.y) / fillY);
      mouthFade = 1 - ramp(.75, 1.15, n);
      const above = averageTone(u2 - .01, MOUTH.y - fillY - .012, u2 + .01, MOUTH.y - fillY + .006);
      const below = averageTone(u2 - .01, MOUTH.y + fillY - .006, u2 + .01, MOUTH.y + fillY + .012);
      const a = above < 0 ? tone : above, b = below < 0 ? tone : below;
      fill = a + (b - a) * ramp(MOUTH.y - fillY, MOUTH.y + fillY, v2);
    }

    cells.push({
      hx: faceL + (c + .5) * cellW, hy: faceT + (r + .5) * cellH,
      u: u2, v: v2,
      x: 0, y: 0, vx: 0, vy: 0,
      tone, eye, lash, edx, edy, eyeSide, z: shape.z, rooted,
      mouthBox, fill, mouthFade,
      // How much an open mouth pulls this character down: the chin and beard below the mouth.
      jaw: gauss(u2, MOUTH.x, .2) * ramp(MOUTH.y + .07, MOUTH.y + .14, v2) * (1 - ramp(MOUTH.y + .18, MOUTH.y + .3, v2) * .6),
      robot: robotTone(u2, v2, tone),
      // How steeply the skull curves here, to hide the side that turns out of view.
      slopeX: shape.sx * TURN_DEPTH,
      slopeY: shape.sy * TURN_DEPTH * faceW / faceH,
      // Gaze: how much the smile and brows pull on this character.
      mouth: gauss(u2, MOUTH.x, .19) * gauss(v2, MOUTH.y, .05),
      mouthSide: Math.max(-1.3, Math.min(1.3, (u2 - MOUTH.x) / .14)),
      teeth: gauss(u2, MOUTH.x, .09) * gauss(v2, MOUTH.y, .012),
      brow: gauss(v2, P.brow, .03) * Math.max(gauss(u2, EYES[0].x, .11), gauss(u2, EYES[1].x, .11)),
      seed: Math.random() * Math.PI * 2,
      // Each character has its own weight and pull home, so nothing moves as one sheet.
      mass: .7 + Math.random() * .7,
      spring: .022 + Math.random() * .03,
      // Decode
      heat: 0, cool: .005 + Math.random() * .016, settle: Math.random() * .5, glitch: 0,
      // Melt: 0 in place, 1 falling, 2 piled up, 3 climbing home
      fall: 0, delay: 0,
    });
  }
  // Skin tone just above the eyes is what the lid closes to.
  lidTone = averageTone(EYES[0].x - .03, EYES[0].y - P.lid[0], EYES[0].x + .03, EYES[0].y - P.lid[1]);
  if (lidTone < 0) lidTone = .6;
  heights = new Float32Array(Math.ceil(W / cellW) + 2);
}
let lidTone = .6, heights = new Float32Array(1), lite = false;

/* ---- pointer (relative to the canvas; a mouse anywhere on the page counts, touch only on the portrait) ---- */
const pointer = { x: -1e4, y: -1e4, on: false, strength: 0 };
function track(e) { const b = canvas.getBoundingClientRect(); pointer.x = e.clientX - b.left; pointer.y = e.clientY - b.top; pointer.on = true; }
addEventListener("pointermove", e => { if (e.pointerType === "mouse") track(e); }, { passive: true });
canvas.addEventListener("pointermove", e => { if (e.pointerType !== "mouse") track(e); }, { passive: true });
canvas.addEventListener("pointerdown", e => {
  track(e);
  lastX = pointer.x; lastY = pointer.y;
  addRing(pointer.x, pointer.y, 24);
  opts.onPoke?.(e);
});
canvas.addEventListener("pointerup", e => { if (e.pointerType !== "mouse") pointer.on = false; });
canvas.addEventListener("pointercancel", () => { pointer.on = false; });
document.documentElement.addEventListener("mouseleave", () => { pointer.on = false; });

/* ---- blink ---- */
let blink = 0, blinkStart = -1, nextBlink = 2.2, blinkDouble = false;
function updateBlink(t) {
  if (t >= nextBlink && blinkStart < 0) blinkStart = t;
  if (blinkStart < 0) { blink = 0; return; }
  const p = (t - blinkStart) / .26;
  if (p >= 1) {
    blink = 0; blinkStart = -1;
    if (!blinkDouble && Math.random() < .2) { blinkDouble = true; nextBlink = t + .12; }
    else { blinkDouble = false; nextBlink = t + 3 + Math.random() * 4.5; }
    return;
  }
  // Lids drop faster than they lift.
  blink = p < .35 ? p / .35 : 1 - (p - .35) / .65;
  blink = blink * blink * (3 - 2 * blink);
}

/* ---- per-character output, filled in by the active effect ---- */
const o = { ax: 0, ay: 0, dx: 0, dy: 0, tone: 0, mix: 0, scale: 1, alpha: 1, glyph: -1, damp: .87, springK: 1, skip: false, under: 0, underX: 0, underY: 0, underTone: 0 };

function glyphFor(tone) {
  // Light ground lifts the midtones so skin keeps some texture instead of going blank.
  let density = isDark ? tone : Math.pow(Math.max(0, 1 - Math.pow(Math.max(0, tone), P.lightTone)), .9);
  // On a light ground, steepen the curve so skin stays airy and the darks (eyes, glasses, brows) read clearly.
  // Darkest characters stop short of the heaviest glyphs, so the portrait stays light.
  if (!isDark) density = Math.max(0, Math.min(1, (density - .3) * 1.15 + .25)) * .84;
  // A floor keeps every part of the head on the page: dark hair on a dark ground, a pale cap on a light one.
  const floor = isDark ? .22 : .1;
  const ti = Math.round((floor + (1 - floor) * density) * (TONES - 1));
  return ti < 0 ? 0 : ti >= TONES ? TONES - 1 : ti;
}

/* ---- ripple state ---- */
let rings = [], lastX = -1e4, lastY = -1e4;
function addRing(x, y, amp) {
  if (current !== "ripple") return;
  rings.push({ x, y, born: now, amp });
  if (rings.length > 10) rings.shift();
}

/* ---- spotlight, wind, melt, head turn and gaze state ---- */
const beam = { x: 0, y: 0 };
const wind = { x: 0, y: 0, px: -1e4, py: -1e4 };
let lastMelt = -10, panelTop = 0;
const turn = { a: 0, b: 0 };
const headPose = { on: false, x: 0, y: 0 };   // from the camera: -1 to 1 each way
// Also from the camera. Left and right are the person's own, which is the same side on screen because the view is mirrored.
const expression = { brow: 0, jaw: 0, blinkL: 0, blinkR: 0, lookX: 0, lookY: 0 };
// The person's lip outline: 20 outer then 20 inner points, as x, y in units of half their resting mouth width.
const lips = { on: false, goal: new Float32Array(80), now: new Float32Array(80), u: new Float32Array(40), v: new Float32Array(40),
  uMin: 0, uMax: 0, vMin: 0, vMax: 0, innerTop: 0, innerHeight: 0 };
const expressionGoal = { ...expression };
const gaze = { x: 0, y: 0, tx: 0, ty: 0, mood: 0, next: 0 };

// Smile and frown amounts for the left and right of the mouth, plus brow lift (positive) or furrow (negative).
function warpExpression(c, smileL, smileR, frownL, frownR, brow) {
  if (c.mouth > .02) {
    const side = c.mouthSide, corners = side * side, right = Math.max(0, Math.min(1, side * .5 + .5));
    const smile = smileL + (smileR - smileL) * right, frown = frownL + (frownR - frownL) * right;
    // Smiling pulls the corners out and up. Frowning draws them in and down, arches the middle, and covers the teeth.
    o.dx += side * c.mouth * (smile * cellW * 2.2 - frown * cellW);
    o.dy += c.mouth * (frown * (corners * 2.4 - .7) - smile * corners * 1.3) * cellH;
    o.tone += c.teeth * smile * .3;
    o.tone += (lidTone - o.tone) * Math.min(1, c.teeth * frown * 1.4);
  }
  if (c.brow > .02) o.dy -= c.brow * brow * cellH * (brow > 0 ? 1.8 : 1.4);
}

/* ---- the effects ---- */
const EFFECTS = {
  scatter: {
    label: "Scatter",
    hint: "Characters are pushed away and spring back.",
    cell(c, hx, hy) {
      if (power < .01) return;
      const dx = hx + c.x - px, dy = hy + c.y - py, d2 = dx * dx + dy * dy;
      if (d2 >= radius * radius) return;
      const d = Math.sqrt(d2) || 1, f = 1 - d / radius, push = f * f * 13 * power / c.mass;
      o.ax = (dx / d) * push - (dy / d) * push * .22;
      o.ay = (dy / d) * push + (dx / d) * push * .22;
    },
  },

  scatter2: {
    label: "Scatter 2",
    hint: "The head turns toward your cursor. Push your face away to find the robot inside.",
    enter() { EFFECTS.turn.enter(); },
    frame() { EFFECTS.turn.frame(); },
    cell(c, hx, hy) {
      EFFECTS.turn.cell(c);
      EFFECTS.scatter.cell(c, hx + o.dx, hy + o.dy);
      // The robot shows through exactly where this character has left its place.
      o.under = Math.min(1, (Math.abs(c.x) + Math.abs(c.y)) / 16);
      if (o.under > .02) {
        // It sits deeper than the face, so it shifts less as the head turns and reads as being inside.
        const free = 1 - c.rooted, x0 = c.hx - turn.mx, y0 = c.hy - turn.my, depth = c.z * faceW * TURN_DEPTH * ROBOT_DEPTH;
        o.underX = (x0 * turn.ca + depth * turn.sa - x0) * free;
        o.underY = (y0 * turn.cb + depth * turn.sb - y0) * free;
        o.underTone = c.robot - turn.sa * (c.u - HEAD.x) * .7 * free;
      }
    },
  },

  decode: {
    label: "Decode",
    hint: "Sweep across the face. Characters scramble, then resolve back.",
    cell(c, hx, hy) {
      if (power > .01) {
        const R = radius * .7, dx = hx - px, dy = hy - py;
        if (dx * dx + dy * dy < R * R) c.heat = 1;
      }
      if (c.heat <= 0) return;
      c.heat -= c.cool;
      if (Math.random() < .28) c.glitch = 8 + (Math.random() * (TONES - 8)) | 0;
      if (c.heat > c.settle) { o.glyph = c.glitch; o.mix = Math.min(1, c.heat * 1.3); }
    },
  },

  xray: {
    label: "X-ray",
    hint: "A lens shows the original photo underneath.",
    cell() {},
    after(swayX, swayY) {
      if (power < .01 || !P.image.complete) return;
      const r = radius * .72 * power;
      ctx.save();
      ctx.beginPath();
      ctx.arc(px * dpr, py * dpr, r * dpr, 0, Math.PI * 2);
      ctx.clip();
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(P.image, (faceL + swayX) * dpr, (faceT + swayY) * dpr, faceW * dpr, faceH * dpr);
      ctx.restore();
      ctx.strokeStyle = pushedColor;
      ctx.lineWidth = 1.5 * dpr;
      ctx.beginPath();
      ctx.arc(px * dpr, py * dpr, r * dpr, 0, Math.PI * 2);
      ctx.stroke();
    },
  },

  spotlight: {
    label: "Spotlight",
    hint: "The face sits in the dark. Your cursor is the flashlight.",
    frame() {
      const idleX = cx + Math.sin(t * .47) * faceW * .28, idleY = cy + Math.sin(t * .31 + 1) * faceH * .2;
      const tx = pointer.on ? px : idleX, ty = pointer.on ? py : idleY;
      beam.x += (tx - beam.x) * .14;
      beam.y += (ty - beam.y) * .14;
    },
    enter() { beam.x = cx; beam.y = cy; },
    cell(c, hx, hy) {
      const dx = hx - beam.x, dy = hy - beam.y, sd = radius * .5;
      o.alpha = .06 + .94 * Math.exp(-(dx * dx + dy * dy) / (2 * sd * sd));
    },
  },

  ripple: {
    label: "Ripple",
    hint: "Moving sends out waves. Click for a bigger one.",
    enter() { rings = []; },
    frame() {
      rings = rings.filter(r => now - r.born < 2.2);
      if (pointer.on && Math.hypot(px - lastX, py - lastY) > 70) {
        addRing(px, py, 9);
        lastX = px; lastY = py;
      }
    },
    cell(c, hx, hy) {
      for (let i = 0; i < rings.length; i++) {
        const r = rings[i], age = now - r.born;
        const dx = hx - r.x, dy = hy - r.y, d = Math.sqrt(dx * dx + dy * dy) || 1;
        const off = d - age * 300;
        if (off > 110 || off < -110) continue;
        const wave = Math.sin(off * .13) * Math.exp(-(off * off) / 2400) * r.amp * (1 - age / 2.2);
        o.dx += (dx / d) * wave;
        o.dy += (dy / d) * wave;
        o.tone += wave * .012;
        o.mix = Math.max(o.mix, Math.min(1, Math.abs(wave) * .07));
      }
    },
  },

  magnify: {
    label: "Magnify",
    hint: "A fisheye lens swells the characters under your cursor.",
    cell(c, hx, hy) {
      if (power < .01) return;
      const R = radius * .78, dx = hx - px, dy = hy - py, d2 = dx * dx + dy * dy;
      if (d2 >= R * R) return;
      const f = 1 - Math.sqrt(d2) / R, s = 1 + 1.3 * power * f * f;
      o.dx = dx * (s - 1);
      o.dy = dy * (s - 1);
      o.scale = s;
    },
  },

  melt: {
    label: "Melt",
    hint: "Characters drip into a pile, then climb back when you stop.",
    enter() { heights.fill(0); },
    frame() {
      if (now - lastMelt > 2.8) heights.fill(0);
    },
    cell(c, hx, hy) {
      if (c.fall === 0) {
        if (power < .01) return;
        const R = radius * .6, dx = hx - px, dy = hy - py;
        if (dx * dx + dy * dy < R * R && Math.random() < .2) {
          c.fall = 1; c.vx = (Math.random() - .5) * 1.2; c.vy = Math.random();
          lastMelt = now;
        }
        return;
      }
      o.skip = true;
      if (c.fall === 1) {
        c.vy += .34 * c.mass;
        c.x += c.vx;
        c.y += c.vy;
        const col = Math.max(0, Math.min(heights.length - 1, ((hx + c.x) / cellW) | 0));
        const floor = panelTop - 2 - heights[col];
        if (hy + c.y >= floor) {
          // Slide off a tall stack toward the lowest spot nearby, so the pile spreads into a mound.
          let low = col;
          for (let n = Math.max(0, col - 6); n <= Math.min(heights.length - 1, col + 6); n++) {
            if (heights[n] < heights[low]) low = n;
          }
          if (heights[low] < heights[col] - cellH) {
            c.x = (low + .5) * cellW - hx;
            return;
          }
          c.y = floor - hy;
          heights[col] += cellH * .5;
          c.vx = c.vy = 0;
          c.fall = 2;
        }
      } else if (c.fall === 2) {
        if (now - lastMelt > 2.8) { c.fall = 3; c.delay = now + Math.random() * .8; }
      } else if (now > c.delay) {
        c.x *= .9;
        c.y *= .9;
        if (Math.abs(c.x) + Math.abs(c.y) < 1) { c.x = c.y = 0; c.fall = 0; }
      }
      o.mix = c.fall === 3 ? .5 : 1;
    },
  },

  wind: {
    label: "Wind",
    hint: "Swipe to blow characters away. A fast swipe carries them further.",
    enter() { wind.x = wind.y = 0; wind.px = px; wind.py = py; },
    frame() {
      const moved = pointer.on && wind.px > -9e3;
      wind.x = wind.x * .72 + (moved ? px - wind.px : 0) * .28;
      wind.y = wind.y * .72 + (moved ? py - wind.py : 0) * .28;
      wind.px = pointer.on ? px : -1e4;
      wind.py = py;
    },
    cell(c, hx, hy) {
      o.damp = .94;
      o.springK = .26;
      const speed = Math.abs(wind.x) + Math.abs(wind.y);
      if (speed < .3) return;
      const R = radius * .6, dx = hx + c.x - px, dy = hy + c.y - py, d2 = dx * dx + dy * dy;
      if (d2 >= R * R) return;
      const f = 1 - Math.sqrt(d2) / R, gust = f * .3 / c.mass;
      const curl = Math.sin(c.seed * 7 + now * 3) * Math.min(speed, 14) * f * .09;
      o.ax = wind.x * gust - wind.y * .02 * curl;
      o.ay = wind.y * gust + curl;
    },
  },

  turn: {
    label: "Head turn",
    hint: "The head turns to look at your cursor.",
    enter() { turn.a = turn.b = 0; },
    frame() {
      const clamp = (v, m) => Math.max(-m, Math.min(m, v));
      // Looking far down reads as a glower, so down gets the least range.
      // The camera wins when it's on; otherwise the head follows the cursor, then drifts when there's neither.
      const steer = headPose.on ? [headPose.x, headPose.y]
        : pointer.on ? [clamp((px - cx) / (faceW * .65), 1), clamp((py - cy) / (faceH * .6), 1)] : null;
      const a = steer ? steer[0] * (steer[0] > 0 ? P.turn.right : P.turn.left) : Math.sin(t * .4) * .1;
      const b = steer ? steer[1] * (steer[1] > 0 ? P.turn.down : P.turn.up) : Math.sin(t * .29) * .05;
      const ease = headPose.on ? .3 : .16;   // quicker than the original .08, so the head keeps up with the cursor
      turn.a += (a - turn.a) * ease;
      turn.b += (b - turn.b) * ease;
      turn.sa = Math.sin(turn.a); turn.ca = Math.cos(turn.a);
      turn.sb = Math.sin(turn.b); turn.cb = Math.cos(turn.b);
      turn.mx = faceL + faceW * HEAD.x; turn.my = faceT + faceH * HEAD.y;
    },
    cell(c) {
      const free = 1 - c.rooted;
      const x0 = c.hx - turn.mx, y0 = c.hy - turn.my, depth = c.z * faceW * TURN_DEPTH;
      o.dx = (x0 * turn.ca + depth * turn.sa - x0) * free;
      o.dy = (y0 * turn.cb + depth * turn.sb - y0) * free;
      // The side turning away from the light dims a little.
      o.tone -= turn.sa * (c.u - HEAD.x) * .7 * free;
      // Whatever curves out of view fades, so the far side doesn't fold over itself.
      const facing = Math.min(turn.ca + turn.sa * c.slopeX, turn.cb + turn.sb * c.slopeY);
      o.alpha = 1 - (1 - Math.max(0, Math.min(1, facing * 5))) * free;
    },
  },

  gaze: {
    label: "Gaze",
    hint: "The eyes follow your cursor. Above the mouth the face smiles, below it frowns.",
    enter() { gaze.mood = 0; },
    frame() {
      if (headPose.on) {
        // Eyes look where the person's eyes look, mirrored.
        gaze.tx = expression.lookX * .5;
        gaze.ty = expression.lookY * .4;
      } else if (pointer.on) {
        gaze.tx = Math.max(-1, Math.min(1, (px - cx) / (faceW * .5))) * .5;
        gaze.ty = Math.max(-1, Math.min(1, (py - (faceT + faceH * EYES[0].y)) / (faceH * .35))) * .4;
      } else if (!still && now > gaze.next) {
        // Nobody around, so the eyes glance about on their own.
        gaze.tx = (Math.random() - .5) * .8;
        gaze.ty = (Math.random() - .5) * .4;
        gaze.next = now + 1.2 + Math.random() * 2.4;
      }
      gaze.x += (gaze.tx - gaze.x) * .32;
      gaze.y += (gaze.ty - gaze.y) * .32;
      // Above the mouth is a smile (+1), below is a frown (-1), with a short blend across the mouth itself.
      const mood = pointer.on ? Math.max(-1, Math.min(1, (faceT + faceH * MOUTH.y - py) / (faceH * .05))) : 0;
      gaze.mood += (mood - gaze.mood) * .09;
    },
    cell(c) {
      // With the camera on, the expression comes from the person in the video instead of the cursor.
      if (!headPose.on) {
        const smile = Math.max(0, gaze.mood), frown = Math.max(0, -gaze.mood);
        warpExpression(c, smile, smile, frown, frown, smile - frown);
      }
      if (c.eye > 0) {
        const ix = (c.edx - gaze.x) / .42, iy = (c.edy - gaze.y) / .75, id = ix * ix + iy * iy;
        const painted = .84 - (id < 1 ? .8 * (1 - id * id) : 0);
        o.tone += (painted - o.tone) * Math.min(1, c.eye * 1.7);
      }
    },
  },
};

/* ---- state (the page supplies the controls) ---- */
const ORDER = Object.keys(EFFECTS);
let current = "scatter";
let currentPhoto = "flannel";
const hint = { _t: "", get textContent() { return this._t; }, set textContent(v) { this._t = v; report(); } };

function choosePhoto(id, instant) {
  currentPhoto = id;
  usePortrait(id);
  layout();
  EFFECTS[current].enter?.();
  // Characters drift in from a little way off, so the swap isn't a hard cut.
  if (!instant && !reduceMotion.matches) {
    for (const c of cells) {
      c.x = (Math.random() - .5) * 60;
      c.y = (Math.random() - .5) * 60;
    }
  }
}

function choose(id) {
  current = id;
  hint.textContent = EFFECTS[id].hint;
  for (const c of cells) { c.heat = 0; c.fall = 0; }
  EFFECTS[id].enter?.();
}

/* ---- camera head tracking (local copy only) ---- */
const TRACKER = "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14";
const FACE_MODEL = "https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task";
let starting = false;
const cameraButton = {
  get disabled() { return starting; }, set disabled(v) { starting = v; report(); },
  setAttribute() { report(); },
  click() { cameraStream ? stopCamera() : startCamera(); },
};
const cameraState = { textContent: "" };
let restFace = null, restFaces = [], lipSamples = [], lipRest = null;
let landmarker = null, cameraStream = null, lastVideoTime = -1, lastLook = 0, lastSeen = 0, rest = null, restSamples = [];

// Where the nose sits between the cheeks and between forehead and chin says which way the head points.
function headAngles(points) {
  const nose = points[1], left = points[234], right = points[454], top = points[10], chin = points[152];
  return {
    yaw: (nose.x - (left.x + right.x) / 2) / (Math.hypot(right.x - left.x, right.y - left.y) || 1),
    pitch: (nose.y - (top.y + chin.y) / 2) / (Math.hypot(chin.x - top.x, chin.y - top.y) || 1),
  };
}

async function loadTracker() {
  if (landmarker) return;
  const { FilesetResolver, FaceLandmarker } = await import(TRACKER + "/vision_bundle.mjs");
  const files = await FilesetResolver.forVisionTasks(TRACKER + "/wasm");
  landmarker = await FaceLandmarker.createFromOptions(files, {
    baseOptions: { modelAssetPath: FACE_MODEL, delegate: "CPU" },   // the GPU path starved the portrait's own drawing
    runningMode: "VIDEO",
    numFaces: 1,
    outputFaceBlendshapes: true,
  });
}

const OUTER_LIP = [61, 146, 91, 181, 84, 17, 314, 405, 321, 375, 291, 409, 270, 269, 267, 0, 37, 39, 40, 185];
const INNER_LIP = [78, 95, 88, 178, 87, 14, 317, 402, 318, 324, 308, 415, 310, 311, 312, 13, 82, 81, 80, 191];

// Lip points relative to the base of the nose, squared up to the face and scaled by its width, so head tilt and distance don't change them.
function readLips(face) {
  const w = preview.videoWidth, h = preview.videoHeight, base = face[2], left = face[234], right = face[454];
  const ax = (right.x - left.x) * w, ay = (right.y - left.y) * h, size = Math.hypot(ax, ay) || 1;
  const ux = ax / size, uy = ay / size, out = new Float32Array(80);
  [...OUTER_LIP, ...INNER_LIP].forEach((index, i) => {
    const dx = (face[index].x - base.x) * w, dy = (face[index].y - base.y) * h;
    out[i * 2] = (dx * ux + dy * uy) / size;
    out[i * 2 + 1] = (-dx * uy + dy * ux) / size;
  });
  return out;
}

// Reads the tracker's muscle scores, compared with the person's resting face so a natural smile or heavy brow reads as neutral.
function readExpression(categories) {
  const score = {};
  for (const c of categories) score[c.categoryName] = c.score;
  return score;
}
function setExpressionGoal(score) {
  const above = (name, gain) => Math.max(0, Math.min(1, (score[name] - restFace[name]) * gain));
  const g = expressionGoal;
  g.brow = above("browInnerUp", 2.2) - Math.max(above("browDownLeft", 2), above("browDownRight", 2));
  g.jaw = above("jawOpen", 1.8);
  // Lids aren't compared with rest: resting scores vary little, and a blink should read as fully closed.
  g.blinkL = ramp(.38, .68, score.eyeBlinkLeft);
  g.blinkR = ramp(.38, .68, score.eyeBlinkRight);
  g.lookX = (score.eyeLookOutLeft + score.eyeLookInRight - score.eyeLookInLeft - score.eyeLookOutRight) * .8;
  g.lookY = (score.eyeLookDownLeft + score.eyeLookDownRight - score.eyeLookUpLeft - score.eyeLookUpRight) * .8;
}

// Runs once per new camera frame where the browser supports it, so the portrait sees each frame as soon as it arrives.
const nextVideoFrame = fn => preview.requestVideoFrameCallback ? preview.requestVideoFrameCallback(fn) : requestAnimationFrame(fn);
function trackHead() {
  if (!cameraStream) return;
  nextVideoFrame(trackHead);
  const clock = performance.now();
  // Up to about 30 looks a second; the camera itself runs at 30.
  if (clock - lastLook < 30 || preview.currentTime === lastVideoTime || preview.readyState < 2) return;
  lastLook = clock;
  lastVideoTime = preview.currentTime;
  let result;
  try {
    result = landmarker.detectForVideo(preview, clock);
  } catch (error) {
    return;    // a frame the tracker can't read, such as while the camera is starting or stopping
  }
  const face = result.faceLandmarks[0];
  const shapes = result.faceBlendshapes?.[0]?.categories;
  let x = 0, y = 0;
  if (face) {
    lastSeen = clock;
    const now = headAngles(face);
    // Whatever you do for the first moment counts as facing forward, so the camera can sit off-center.
    if (!rest) {
      restSamples.push(now);
      if (shapes) restFaces.push(readExpression(shapes));
      lipSamples.push(readLips(face));
      if (restSamples.length >= 15) {
        // The resting mouth sets where the portrait's mouth sits and how wide it is.
        const lipMean = new Float32Array(80);
        for (const sample of lipSamples) sample.forEach((value, i) => { lipMean[i] += value / lipSamples.length; });
        let centerX = 0, centerY = 0;
        for (let i = 0; i < 20; i++) { centerX += lipMean[i * 2] / 20; centerY += lipMean[i * 2 + 1] / 20; }
        lipRest = { x: centerX, y: centerY, half: Math.abs(lipMean[20] - lipMean[0]) / 2 || .1 };
        restFace = {};
        for (const name in restFaces[0] || {}) restFace[name] = restFaces.reduce((sum, f) => sum + f[name], 0) / restFaces.length;
        const mean = key => restSamples.reduce((sum, s) => sum + s[key], 0) / restSamples.length;
        rest = { yaw: mean("yaw"), pitch: mean("pitch") };
        hint.textContent = "Turn your head, raise your brows, blink, and try any mouth shape. The portrait copies it.";
      }
      return;
    }
    if (shapes && restFace) setExpressionGoal(readExpression(shapes));
    if (lipRest) {
      const raw = readLips(face);
      for (let i = 0; i < 40; i++) {
        lips.goal[i * 2] = (raw[i * 2] - lipRest.x) / lipRest.half;
        lips.goal[i * 2 + 1] = (raw[i * 2 + 1] - lipRest.y) / lipRest.half;
      }
      if (!lips.on) { lips.now.set(lips.goal); lips.on = true; }
    }
    x = Math.max(-1, Math.min(1, -(now.yaw - rest.yaw) / .26));
    y = Math.max(-1, Math.min(1, (now.pitch - rest.pitch) / .12));
  } else if (clock - lastSeen < 600) {
    return;    // a brief dropout: hold the last pose
  } else {
    Object.assign(expressionGoal, { brow: 0, jaw: 0, blinkL: 0, blinkR: 0, lookX: 0, lookY: 0 });
  }
  headPose.x += (x - headPose.x) * .6;
  headPose.y += (y - headPose.y) * .6;
}

function stopCamera() {
  cameraStream?.getTracks().forEach(track => track.stop());
  cameraStream = null;
  headPose.on = false;
  if (lite) { lite = false; layout(); }
  for (const key in expression) expression[key] = expressionGoal[key] = 0;
  lips.on = false;
  preview.srcObject = null;
  preview.hidden = true;
  cameraButton.setAttribute("aria-pressed", "false");
  cameraState.textContent = "Use camera";
  hint.textContent = EFFECTS[current].hint;
}

async function startCamera() {
  cameraState.textContent = "Starting…";
  cameraButton.disabled = true;
  try {
    if (!navigator.mediaDevices?.getUserMedia) throw Object.assign(new Error("insecure"), { name: "InsecureContext" });
    cameraStream = await navigator.mediaDevices.getUserMedia({ video: { width: { ideal: 480 }, height: { ideal: 360 }, frameRate: { ideal: 30 }, facingMode: "user" }, audio: false });
    hint.textContent = "Loading the face tracker. Your video stays on this device.";
    await loadTracker();
    preview.srcObject = cameraStream;
    preview.hidden = false;
    await preview.play();
    rest = null; restSamples = []; restFace = null; restFaces = []; lipSamples = []; lipRest = null; lips.on = false; lastVideoTime = -1; lastSeen = performance.now();
    headPose.x = headPose.y = 0;
    headPose.on = true;
    lite = true; layout();
    if (current !== "turn" && current !== "scatter2") choose("turn");
    hint.textContent = "Look straight ahead for a moment.";
    cameraButton.setAttribute("aria-pressed", "true");
    cameraState.textContent = "Camera on";
    trackHead();
  } catch (error) {
    stopCamera();
    hint.textContent = error.name === "NotAllowedError" ? "Camera blocked. Allow it in your browser's site settings, then try again."
      : error.name === "NotFoundError" ? "No camera found, so the head will keep following your cursor."
      : error.name === "InsecureContext" ? "The camera needs this page served from localhost or https. The head keeps following your cursor."
      : "The face tracker didn't load. Check your connection and try again.";
  }
  cameraButton.disabled = false;
}

// Turns the eased lip outline into portrait positions, mirrored so the person's left is on the left of the screen.
function placeLips() {
  const width = P.mouthW, height = width * PORTRAIT_ASPECT;
  for (let i = 0; i < 80; i++) lips.now[i] += (lips.goal[i] - lips.now[i]) * .6;
  for (let i = 0; i < 40; i++) {
    lips.u[i] = MOUTH.x - lips.now[i * 2] * width;
    lips.v[i] = MOUTH.y + lips.now[i * 2 + 1] * height;
  }
  // A closed mouth still gets a dark line at least a row or so tall, or it would vanish between characters.
  let top = 9, bottom = -9, middle = 0;
  for (let i = 20; i < 40; i++) { top = Math.min(top, lips.v[i]); bottom = Math.max(bottom, lips.v[i]); middle += lips.v[i] / 20; }
  const least = 1.3 / faceRows;
  if (bottom - top < least) {
    const grow = least / Math.max(bottom - top, .0005);
    for (let i = 20; i < 40; i++) lips.v[i] = middle + (lips.v[i] - middle) * grow;
    top = middle - least / 2; bottom = middle + least / 2;
  }
  lips.innerTop = top; lips.innerHeight = bottom - top;
  lips.uMin = Math.min(...lips.u); lips.uMax = Math.max(...lips.u);
  lips.vMin = Math.min(...lips.v); lips.vMax = Math.max(...lips.v);
}

function insideLips(u, v, from, to) {
  let inside = false;
  for (let i = from, j = to - 1; i < to; j = i++) {
    if ((lips.v[i] > v) !== (lips.v[j] > v) && u < (lips.u[j] - lips.u[i]) * (v - lips.v[i]) / (lips.v[j] - lips.v[i]) + lips.u[i]) inside = !inside;
  }
  return inside;
}

/* ---- frame ---- */
function frame(ms) {
  requestAnimationFrame(frame);
  if (!cells.length || !visible) return;
  still = reduceMotion.matches;
  now = ms / 1000;
  t = still ? 0 : now;
  if (!still) updateBlink(t);

  pointer.strength += ((pointer.on ? 1 : 0) - pointer.strength) * .3;
  px = pointer.x; py = pointer.y; power = pointer.strength;

  if (headPose.on) {
    // Scores arrive about 15 times a second; easing every frame keeps the face moving smoothly between them.
    for (const key in expression) expression[key] += (expressionGoal[key] - expression[key]) * (key.startsWith("blink") ? .7 : .4);
  }

  if (lips.on) placeLips();

  const effect = EFFECTS[current];
  effect.frame?.();

  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const breathe = still ? 0 : Math.sin(t * .85) * .0035;
  const swayX = still ? 0 : Math.sin(t * .37) * .9;
  const swayY = still ? 0 : Math.sin(t * .53 + 1) * .7;
  const sw = sheet.w, sh = sheet.h;
  let alphaNow = 1;

  for (let i = 0; i < cells.length; i++) {
    const c = cells[i];

    // Resting pose: the head breathes and sways by about a pixel, so the structure never shifts.
    const homeX = c.hx + (c.hx - cx) * breathe + swayX;
    const homeY = c.hy + (c.hy - cy) * breathe + swayY;

    // A slow wave of light across the face and a faint per-character flicker.
    let tone = c.tone;
    if (!still) {
      tone += Math.sin(c.hx * .021 + t * .55) * Math.cos(c.hy * .017 - t * .41) * .035;
      tone += Math.sin(t * 1.3 + c.seed * 5) * .018;
    }

    o.ax = o.ay = o.dx = o.dy = o.mix = 0;
    o.tone = tone; o.scale = 1; o.alpha = 1; o.glyph = -1; o.damp = .87; o.springK = 1; o.skip = false; o.under = 0;
    effect.cell(c, homeX, homeY);
    if (headPose.on) {
      const e = expression;
      warpExpression(c, 0, 0, 0, 0, e.brow);
      if (c.jaw > .02) o.dy += c.jaw * e.jaw * cellH * 2.5;
      if (lips.on && c.mouthBox) {
        // The photo's own mouth is painted out and the person's mouth is drawn in its place.
        o.tone += (c.fill - o.tone) * c.mouthFade;
        if (c.u > lips.uMin && c.u < lips.uMax && c.v > lips.vMin && c.v < lips.vMax && insideLips(c.u, c.v, 0, 20)) {
          if (insideLips(c.u, c.v, 20, 40)) {
            // Inside the lips: dark, with a row of teeth at the top once the mouth is open enough to show them.
            const open = lips.innerHeight * faceRows >= 2.4;
            o.tone = open && c.v < lips.innerTop + lips.innerHeight * .42 ? .96 : .03;
          } else {
            o.tone = .8;
          }
        }
      }
    }

    if (!o.skip) {
      c.vx = (c.vx - c.x * c.spring * o.springK + o.ax) * o.damp;
      c.vy = (c.vy - c.y * c.spring * o.springK + o.ay) * o.damp;
      c.x += c.vx;
      c.y += c.vy;
    }

    tone = o.tone;
    // The person's own blinks replace the automatic ones while the camera is on.
    const lid = headPose.on ? (c.eyeSide ? expression.blinkR : expression.blinkL) : blink;
    if (c.eye && lid) {
      tone += (lidTone - tone) * Math.min(1, lid * c.eye * 1.25);
      tone -= c.lash * lid * .4;
    }

    const ti = o.glyph >= 0 ? o.glyph : glyphFor(tone);

    const moved = Math.abs(c.x) + Math.abs(c.y);
    let mi = Math.max((moved / 40) | 0, Math.round(o.mix * (MIXES - 1)));
    if (mi >= MIXES) mi = MIXES - 1;
    // Play look: bands of color drift diagonally across the head.
    if (rainbow) mi = MIXES + Math.floor((((c.u * .9 + c.v * .7 - t * .07) % 1 + 1) % 1) * RAINBOW_ROWS);

    if (o.under > .02) {
      const glow = c.robot >= .9 && !still ? Math.sin(now * 2.4) * .08 - .08 : 0;
      ctx.globalAlpha = alphaNow = o.under * o.alpha;
      ctx.drawImage(sheet.canvas, glyphFor(o.underTone + glow) * sw, 0, sw, sh,
        (homeX + o.underX) * dpr - sw / 2, (homeY + o.underY) * dpr - sh / 2, sw, sh);
    }

    if (o.alpha < .02) continue;
    if (o.alpha !== alphaNow) { ctx.globalAlpha = alphaNow = o.alpha; }

    const x = homeX + c.x + o.dx, y = homeY + c.y + o.dy;
    if (o.scale > 1.05) {
      const b = bigSheet, dw = sw * o.scale, dh = sh * o.scale;
      ctx.drawImage(b.canvas, ti * b.w, mi * b.h, b.w, b.h, x * dpr - dw / 2, y * dpr - dh / 2, dw, dh);
    } else {
      ctx.drawImage(sheet.canvas, ti * sw, mi * sh, sw, sh, x * dpr - sw / 2, y * dpr - sh / 2, sw, sh);
    }
  }
  ctx.globalAlpha = 1;
  effect.after?.(swayX, swayY);
}


/* ---- start ---- */
let resizeTimer;
new ResizeObserver(() => { clearTimeout(resizeTimer); resizeTimer = setTimeout(layout, 120); }).observe(canvas);
// Skip drawing while the portrait is scrolled out of view.
new IntersectionObserver(entries => { visible = entries[0].isIntersecting; }).observe(canvas);
if (opts.look) setLook(opts.look);
current = EFFECTS[opts.effect] ? opts.effect : "scatter";
choosePhoto(PORTRAITS[opts.photo] ? opts.photo : "flannel", true);
choose(current);
requestAnimationFrame(frame);
// The first sheets may use the fallback face; redraw them once the real one arrives.
if (document.fonts && document.fonts.load) {
  document.fonts.load("16px 'Fragment Mono'").then(faces => { if (faces.length) layout(); }).catch(() => {});
}

return {
  effects: ORDER.map(id => ({ id, label: EFFECTS[id].label })),
  setEffect: choose,
  setPhoto: id => choosePhoto(id),
  setLook,
  toggleCamera: () => cameraButton.click(),
  stopCamera: () => { if (cameraStream) stopCamera(); },
  // A burst that throws every character outward, then lets them spring home.
  burst(strength = 22) {
    if (reduceMotion.matches) return;
    for (const c of cells) {
      const dx = c.hx - cx, dy = c.hy - cy, d = Math.hypot(dx, dy) || 1;
      c.vx += dx / d * strength * (.5 + Math.random()) / c.mass;
      c.vy += dy / d * strength * (.5 + Math.random()) / c.mass - 4;
    }
  },
};
};
